SELECT EXISTS (
 SELECT 1 FROM service_email_addresses s
 WHERE LOWER(BTRIM(s.address,U&' \0009\000A\000B\000C\000D\0085\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000'))=LOWER(BTRIM(u.email,U&' \0009\000A\000B\000C\000D\0085\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000'))
) AS is_service_mail
FROM conversations c JOIN users u ON u.id=c.contact_id
WHERE c.uuid=$1::uuid AND NULLIF(BTRIM(u.email,U&' \0009\000A\000B\000C\000D\0085\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000'),'') IS NOT NULL;
